None.ex:
def keres(lista, x):
    for v in lista:
        if v == x:
            return v
    return None

print(keres(['A'], 'B'))   # None

break.ex:
for v in [1, 2, 3, 4]:
    if v == 3:
        break
    print(v)
# kiírja: 1, 2

continue.ex:
for v in [1, 2, 3]:
    if v == 2:
        continue
    print(v)
# kiírja: 1, 3

enumerate.ex:
for i, v in enumerate(['a', 'b']):
    print(i, v)
# kiírja: 0 a, majd 1 b

zip.ex:
for x, y in zip([1, 2], ['a', 'b']):
    print(x, y)
# kiírja: 1 a, majd 2 b

items.ex:
